<script setup lang="ts">
import { onUnmounted,ref,shallowRef } from 'vue';
import {composeShortDramaVideo,getShortDramaComposeStatus,downloadShortDramaVideo} from '@/api/shortDrama';
import type {ShortDramaComposeVideoResult,ShortDramaAspectRatio,ShortDramaTransitionType} from '@/api/shortDrama/types';
import type {CanvasNode} from '@/utils/dramaCanvas';
const props=defineProps<{projectId:string;videos:CanvasNode[];readyIds:string[]}>();
const emit=defineEmits<{close:[]}>();
const ratio=ref<ShortDramaAspectRatio>('16:9'),transition=ref<ShortDramaTransitionType>('none'),busy=shallowRef(false),error=shallowRef(''),result=ref<ShortDramaComposeVideoResult>();
let timer:ReturnType<typeof setTimeout>|undefined, alive=true;
async function query(){try{const value=await getShortDramaComposeStatus(props.projectId);if(value)result.value=value;if(alive&&(value?.status==='pending'||value?.status==='processing'))timer=setTimeout(()=>void query(),5000);}catch(e){error.value=String(e);}}
async function start(){busy.value=true;error.value='';try{const ids=props.videos.map(n=>n.data.business?.id).filter((id):id is string=>!!id);if(ids.length!==props.videos.length||ids.some(id=>!props.readyIds.includes(id)))throw new Error('请先保存并生成画布中的全部视频节点');result.value=await composeShortDramaVideo(props.projectId,{storyboardIds:ids,aspectRatio:ratio.value,transitionType:transition.value,transitionDurationSeconds:.3,watermark:true});await query();}catch(e){error.value=e instanceof Error?e.message:'合成失败';}finally{busy.value=false;}}
async function download(){busy.value=true;try{const blob=await downloadShortDramaVideo(props.projectId);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='短剧成片.mp4';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=String(e);}finally{busy.value=false;}}
onUnmounted(()=>{alive=false;clearTimeout(timer);});
</script>
<template><el-dialog :model-value="true" title="按画布镜头顺序合成" width="min(560px,94vw)" append-to-body @close="emit('close')"><p class="compose-note">视频之间的连线确定前后顺序，其余镜头按设置的镜头顺序排列。</p><ol class="compose-list"><li v-for="n in videos" :key="n.id">{{n.data.title}}<small>{{readyIds.includes(n.data.business?.id || '') ? '视频就绪' : '待生成'}}</small></li></ol><el-form label-position="top"><el-form-item label="成片画幅"><el-select v-model="ratio"><el-option v-for="r in ['16:9','9:16','1:1','4:3','3:4','21:9']" :key="r" :label="r" :value="r"/></el-select></el-form-item><el-form-item label="镜头转场"><el-select v-model="transition"><el-option label="无转场" value="none"/><el-option label="溶解" value="dissolve"/><el-option label="淡入淡出" value="fade"/><el-option label="滑动" value="slide"/></el-select></el-form-item></el-form><p v-if="result">合成状态：{{result.status}} · {{result.progress || 0}}%</p><p v-if="result?.errorMessage || error" role="alert">{{error || result?.errorMessage}}</p><template #footer><el-button @click="emit('close')">关闭</el-button><el-button v-if="result?.status==='done'" :loading="busy" type="primary" @click="download">下载成片</el-button><el-button v-else :loading="busy" type="primary" :disabled="!videos.length || result?.status==='processing' || result?.status==='pending'" @click="start">开始合成 {{videos.length}} 个镜头</el-button></template></el-dialog></template>
<style scoped>.compose-note{font-size:12px;line-height:1.8;color:var(--drama-text-secondary)}.compose-list{max-height:240px;overflow:auto;padding-left:24px;margin:20px 0}.compose-list li{font-size:12px;padding:8px 0}.compose-list small{float:right;color:var(--drama-text-tertiary)}</style>
